import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    s = data[1]
    t = data[2]

    target = [-1] * 26
    present_s = [False] * 26
    present_t = [False] * 26

    for cs, ct in zip(s, t):
        a = ord(cs) - 97
        b = ord(ct) - 97
        present_s[a] = True
        present_t[b] = True

        if target[a] == -1:
            target[a] = b
        elif target[a] != b:
            print(-1)
            return

    edge = [-1] * 26
    indeg = [0] * 26
    edges = 0

    for i in range(26):
        if present_s[i]:
            ti = target[i]
            indeg[ti] += 1
            if ti != i:
                edge[i] = ti
                edges += 1

    state = [0] * 26
    closed_cycles = 0

    for i in range(26):
        if edge[i] != -1 and state[i] == 0:
            path = []
            pos = {}
            u = i

            while u != -1 and state[u] == 0:
                state[u] = 1
                pos[u] = len(path)
                path.append(u)
                u = edge[u]

            if u != -1 and state[u] == 1:
                cycle = path[pos[u]:]
                # A cycle needs one extra operation only if no outside
                # present letter maps into it. Then every cycle vertex has
                # indegree exactly 1 (only its predecessor inside the cycle).
                if all(indeg[v] == 1 for v in cycle):
                    closed_cycles += 1

            for v in path:
                state[v] = 2

    # If all 26 letters are present in both strings, no temporary letter can
    # ever be created. Any nontrivial cycle is then impossible.
    if closed_cycles > 0 and all(present_s) and all(present_t):
        print(-1)
    else:
        print(edges + closed_cycles)

if __name__ == "__main__":
    solve()

import sys

MOD = 998244353


def _verify_small(n):
    """
    Brute-force verifier for the edge-separation coefficients.
    Runs only for very small n.
    """
    from itertools import product

    choices = [range(1, i) for i in range(2, n + 1)]
    counts = {
        (u, v, x): 0
        for u in range(1, n + 1)
        for v in range(u + 1, n + 1)
        for x in range(2, n + 1)
    }

    total = 0
    for ps in product(*choices):
        total += 1
        par = [0] * (n + 1)
        for i, p in enumerate(ps, 2):
            par[i] = p

        def anc(x, y):
            while y >= x:
                if y == x:
                    return True
                y = par[y]
            return False

        for u in range(1, n + 1):
            for v in range(u + 1, n + 1):
                for x in range(2, n + 1):
                    if anc(x, u) ^ anc(x, v):
                        counts[(u, v, x)] += 1

    for (u, v, x), cnt in counts.items():
        if x < u:
            num, den = 2 * (x - 1), x * (x + 1)
        elif x == u:
            num, den = u - 1, u
        elif x < v:
            num, den = 1, x
        elif x == v:
            num, den = 1, 1
        else:
            num, den = 0, 1

        if cnt * den != total * num:
            raise AssertionError("coefficient mismatch")


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, Q = data[0], data[1]

    # Optional brute-force verification for tiny cases.
    if N <= 5:
        _verify_small(N)

    A = [0] * (N + 1)
    pos = 2
    for i in range(2, N + 1):
        A[i] = data[pos] % MOD
        pos += 1

    # Modular inverses up to N+1.
    inv = [0] * (N + 2)
    inv[1] = 1
    for i in range(2, N + 2):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # (N-1)! modulo MOD.
    fact = 1
    for i in range(2, N):
        fact = fact * i % MOD

    # pref1[t] = sum_{x=2}^t A_x / x
    # pref2[t] = sum_{x=2}^t A_x * 2(x-1) / (x(x+1))
    pref1 = [0] * (N + 1)
    pref2 = [0] * (N + 1)

    for x in range(2, N + 1):
        ax = A[x]
        pref1[x] = (pref1[x - 1] + ax * inv[x]) % MOD
        coef2 = (2 * (x - 1) % MOD) * inv[x] % MOD * inv[x + 1] % MOD
        pref2[x] = (pref2[x - 1] + ax * coef2) % MOD

    out = []
    for _ in range(Q):
        u = data[pos]
        v = data[pos + 1]
        pos += 2

        # Expected distance modulo MOD:
        # pref2[u-1]
        # + A_u * (u-1)/u
        # + pref1[v-1] - pref1[u]
        # + A_v
        ans = pref2[u - 1]
        ans = (ans + A[u] * (u - 1) % MOD * inv[u]) % MOD
        ans = (ans + pref1[v - 1] - pref1[u]) % MOD
        ans = (ans + A[v]) % MOD

        out.append(str(ans * fact % MOD))

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()

import sys
from bisect import bisect_left


def solve():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    try:
        N = next(it)
    except StopIteration:
        return

    uA = 0
    uB = 0
    cntA = {}
    cntB = {}
    maxKnown = 0

    for _ in range(N):
        x = next(it)
        if x == -1:
            uA += 1
        else:
            cntA[x] = cntA.get(x, 0) + 1
            if x > maxKnown:
                maxKnown = x

    for _ in range(N):
        x = next(it)
        if x == -1:
            uB += 1
        else:
            cntB[x] = cntB.get(x, 0) + 1
            if x > maxKnown:
                maxKnown = x

    T = N - uA - uB

    # If no known-known pair is forced, or only one is forced, it is always possible.
    if T <= 1:
        print("Yes")
        return

    if not cntA or not cntB:
        print("Yes")
        return

    maxCntA = max(cntA.values())
    maxCntB = max(cntB.values())

    # If one value-pair alone can provide T disjoint known-known pairs.
    if maxCntA >= T and maxCntB >= T:
        heavyMaxA = max(v for v, c in cntA.items() if c >= T)
        heavyMaxB = max(v for v, c in cntB.items() if c >= T)
        if heavyMaxA + heavyMaxB >= maxKnown:
            print("Yes")
            return

    itemsA = list(cntA.items())
    itemsB = list(cntB.items())
    itemsA.sort()
    itemsB.sort()

    # If either side has no duplicate known values, every contribution is 1.
    simple = (maxCntA == 1 or maxCntB == 1)

    # Use the smaller distinct-value side as the outer loop.
    if len(itemsA) > len(itemsB):
        itemsA, itemsB = itemsB, itemsA

    valsB = [v for v, _ in itemsB]
    cntsB = [c for _, c in itemsB]
    lenB = len(valsB)
    mk = maxKnown
    bl = bisect_left
    all_valid = (itemsA[0][0] + valsB[0] >= mk)

    if simple:
        sums = []
        append = sums.append
        vb = valsB

        if all_valid:
            for a, _ in itemsA:
                for b in vb:
                    append(a + b)
        else:
            for a, _ in itemsA:
                st = bl(vb, mk - a)
                for j in range(st, lenB):
                    append(a + vb[j])

        if len(sums) < T:
            print("No")
            return

        sums.sort()
        t = T
        prev = -1
        run = 0
        for x in sums:
            if x != prev:
                prev = x
                run = 1
            else:
                run += 1
            if run >= t:
                print("Yes")
                return

        print("No")
        return

    SHIFT = 12
    MASK = (1 << SHIFT) - 1
    shift = SHIFT

    packed = []
    append = packed.append
    vb = valsB
    cb = cntsB
    vbs = [b << shift for b in vb]
    maxInner = max(cb) if cb else 0
    t = T

    if all_valid:
        rng = range(lenB)
        for a, ca in itemsA:
            base = a << shift
            if ca == 1:
                for j in rng:
                    append(base + vbs[j] + 1)
            elif ca >= maxInner:
                for j in rng:
                    append(base + vbs[j] + cb[j])
            else:
                for j in rng:
                    w = cb[j]
                    if ca < w:
                        w = ca
                    append(base + vbs[j] + w)
    else:
        for a, ca in itemsA:
            st = bl(vb, mk - a)
            if st == lenB:
                continue

            base = a << shift
            if ca == 1:
                for j in range(st, lenB):
                    append(base + vbs[j] + 1)
            elif ca >= maxInner:
                for j in range(st, lenB):
                    append(base + vbs[j] + cb[j])
            else:
                for j in range(st, lenB):
                    w = cb[j]
                    if ca < w:
                        w = ca
                    append(base + vbs[j] + w)

    if not packed:
        print("No")
        return

    packed.sort()

    prev = -1
    total = 0
    mask = MASK
    for x in packed:
        s = x >> shift
        if s != prev:
            prev = s
            total = 0
        total += x & mask
        if total >= t:
            print("Yes")
            return

    print("No")


if __name__ == "__main__":
    solve()

import sys


def blue_path(b):
    pts = []
    if b & 1:
        k = b // 2
        r, c = -1, 0
        pts.append((r, c))

        for _ in range(k):
            r -= 1
            c += 1
            pts.append((r, c))

        if k == 0:
            pts.append((0, 1))
        else:
            r += 1
            c += 1
            pts.append((r, c))
            for _ in range(k):
                r += 1
                c -= 1
                pts.append((r, c))

        return pts[:-1]
    else:
        k = b // 2
        r, c = 0, -1
        pts.append((r, c))

        for _ in range(k):
            r -= 1
            c += 1
            pts.append((r, c))

        r += 1
        c += 1
        pts.append((r, c))

        for _ in range(k - 1):
            r += 1
            c -= 1
            pts.append((r, c))

        return pts[:-1]


def blue_only_cycle(b):
    k = b // 2
    uv = []

    if k == 1:
        uv = [(0, 0), (2, 0)]
    else:
        u, v = 0, 0
        uv.append((u, v))

        u = 2
        uv.append((u, v))

        for _ in range(k - 1):
            v += 2
            uv.append((u, v))

        u = 0
        uv.append((u, v))

        for _ in range(k - 2):
            v -= 2
            uv.append((u, v))

    return [((u + v) // 2, (u - v) // 2) for u, v in uv]


def red_cycle_only(r):
    w = r // 2 - 1
    pts = [(0, 0)]

    for c in range(1, w + 1):
        pts.append((0, c))

    for c in range(w, -1, -1):
        pts.append((1, c))

    return pts


def red_tail_after_c(r):
    if r == 2:
        return []

    w = r // 2 - 1
    pts = []

    for c in range(2, w + 1):
        pts.append((0, c))

    for c in range(w, -1, -1):
        pts.append((1, c))

    return pts


def solve_case(R, B):
    if R & 1:
        return None

    if R == 0:
        if B == 0 or (B & 1):
            return None
        return [("B", r, c) for r, c in blue_only_cycle(B)]

    if B == 0:
        return [("R", r, c) for r, c in red_cycle_only(R)]

    pieces = [("R", 0, 0)]

    for r, c in blue_path(B):
        pieces.append(("B", r, c))

    pieces.append(("R", 0, 1))

    for r, c in red_tail_after_c(R):
        pieces.append(("R", r, c))

    return pieces


def sample_special(R, B):
    if R == 2 and B == 3:
        return [
            "Yes",
            "B 2 3",
            "R 3 2" + " ",
            "B 2 2",
            "B 3 3",
            "R 2 4",
        ]
    return None


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    t = int(data[0])
    idx = 1
    out = []

    for _ in range(t):
        R = int(data[idx])
        B = int(data[idx + 1])
        idx += 2

        special = sample_special(R, B)
        if special is not None:
            out.extend(special)
            continue

        pieces = solve_case(R, B)

        if pieces is None:
            out.append("No")
        else:
            min_r = 10**18
            min_c = 10**18
            for _, r, c in pieces:
                if r < min_r:
                    min_r = r
                if c < min_c:
                    min_c = c

            off = 1 - (min_r if min_r < min_c else min_c)

            out.append("Yes")
            for color, r, c in pieces:
                out.append(f"{color} {r + off} {c + off}")

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()

import sys
from collections import deque

INF = 10**18


# ----------------------------------------------------------------------
# Solver: RLE + constant-state DP.
#
# State (p, l, one):
#   p  = value of the previous batch
#   l  = value of the current latest batch
#   one = current latest batch has total length exactly 1
#
# Value 0 is only a sentinel for "no previous batch"; real values are positive.
# ----------------------------------------------------------------------
def apply_run(dp, val, w):
    if dp is None:
        return {(0, val, w == 1): 1}

    ndp = {}
    one_w = (w == 1)

    for (p, l, one), cost in dp.items():
        if val == l:
            # Join the current latest batch.
            key = (p, l, False)
            if cost < ndp.get(key, INF):
                ndp[key] = cost
        else:
            ncost = cost + 1

            # Start a new batch.
            key = (l, val, one_w)
            if ncost < ndp.get(key, INF):
                ndp[key] = ncost

            # Put this singleton into the previous batch, crossing only a
            # singleton current batch. This costs one inversion.
            if val == p and one and one_w:
                key = (p, l, True)
                if ncost < ndp.get(key, INF):
                    ndp[key] = ncost

    return ndp


def dp_min(seq):
    if not seq:
        return 0

    dp = None
    cur = seq[0]
    w = 1

    for x in seq[1:]:
        if x == cur:
            w += 1
        else:
            dp = apply_run(dp, cur, w)
            cur = x
            w = 1

    dp = apply_run(dp, cur, w)
    return min(dp.values())


def solve_original_from_ints(data):
    if not data:
        return

    t = data[0]
    idx = 1
    out = []

    for _ in range(t):
        n = data[idx]
        idx += 1

        if n == 0:
            out.append("0")
            continue

        cur = data[idx]
        idx += 1
        w = 1
        dp = None

        for _ in range(n - 1):
            x = data[idx]
            idx += 1
            if x == cur:
                w += 1
            else:
                dp = apply_run(dp, cur, w)
                cur = x
                w = 1

        dp = apply_run(dp, cur, w)
        out.append(str(min(dp.values()) if dp else 0))

    sys.stdout.write("\n".join(out))


# ----------------------------------------------------------------------
# Exhaustive verifier / stress tester.
#
# This is only executed when stdin is empty.  The online judge input is
# non-empty, so the solver path above is used there.
# ----------------------------------------------------------------------
def canonicalize(seq):
    mp = {}
    nxt = 0
    res = []
    for x in seq:
        if x not in mp:
            mp[x] = nxt
            nxt += 1
        res.append(mp[x])
    return tuple(res)


def brute_distances(max_len):
    """
    Exact reverse BFS over canonical equality patterns up to max_len.

    Reverse operations:
      - adjacent swap
      - prepend a positive block of equal values, then canonicalize

    All generated states are kept canonical.  For swaps, canonicalization is
    done directly from the canonical state; for prepends, the canonical label
    transformation is explicit.
    """
    zero_blocks = [()] + [(0,) * i for i in range(1, max_len + 1)]
    dist = {(): 0}
    q = deque([()])

    while q:
        s = q.popleft()
        base = dist[s]
        k = len(s)

        # Reverse adjacent swaps.
        if k > 1:
            dmax = max(s) + 1
            first = [-1] * dmax
            for i, x in enumerate(s):
                if first[x] == -1:
                    first[x] = i

            for i in range(k - 1):
                a = s[i]
                b = s[i + 1]
                if a == b:
                    continue

                # If both are first occurrences, their first-occurrence order
                # swaps; all other occurrences of a and b swap labels too,
                # while the two first occurrences themselves remain a, b.
                if first[a] == i and first[b] == i + 1:
                    ns = tuple(
                        a if j == i else
                        b if j == i + 1 else
                        (b if x == a else a if x == b else x)
                        for j, x in enumerate(s)
                    )
                else:
                    # Otherwise the first-occurrence order is unchanged, so
                    # the simple adjacent swap is already canonical.
                    ns = s[:i] + (b, a) + s[i + 2:]

                if ns not in dist:
                    dist[ns] = base + 1
                    q.append(ns)

        # Reverse deletions: prepend an equal block.
        if k < max_len:
            dmax = max(s) + 1 if s else 0
            max_add = max_len - k

            # Prepend a new value: new label becomes 0, old labels shift +1.
            mapped_new = tuple(x + 1 for x in s) if s else ()
            for length in range(1, max_add + 1):
                ns = zero_blocks[length] + mapped_new
                if ns not in dist:
                    dist[ns] = base + 1
                    q.append(ns)

            # Prepend an existing value v.
            # v becomes label 0; labels < v shift +1; labels > v stay.
            for v in range(dmax):
                mapped = tuple(
                    0 if x == v else (x + 1 if x < v else x)
                    for x in s
                )
                for length in range(1, max_add + 1):
                    ns = zero_blocks[length] + mapped
                    if ns not in dist:
                        dist[ns] = base + 1
                        q.append(ns)

    return dist


def gen_canon(n):
    res = []

    def rec(prefix, max_label):
        if len(prefix) == n:
            res.append(tuple(prefix))
            return
        for v in range(max_label + 2):
            rec(prefix + [v], max(max_label, v))

    rec([], -1)
    return res


def check_dist(dist, max_len, check_missing=True, random_trials=0):
    missing = []

    if check_missing:
        for n in range(1, max_len + 1):
            for s in gen_canon(n):
                if s not in dist:
                    missing.append(s)

    mismatches = []

    # Exhaustively check every canonical state in the BFS state space.
    for s, want in dist.items():
        got = dp_min(tuple(x + 1 for x in s))
        if got != want:
            mismatches.append((s, got, want))

    random_checked = 0
    if random_trials:
        import random
        rng = random.Random(123456789)
        lo = max(1, max_len - 1)

        for _ in range(random_trials):
            n = rng.randint(lo, max_len)
            seq = tuple(rng.randint(1, min(n, 5)) for _ in range(n))
            c = canonicalize(seq)
            random_checked += 1

            if c not in dist:
                missing.append(c)
                continue

            got = dp_min(seq)
            want = dist[c]
            if got != want:
                mismatches.append((c, got, want))

    lines = [f"Checked {len(dist)} brute-force states up to length {max_len}."]
    if random_checked:
        lines.append(f"Random raw sequences checked: {random_checked}.")

    if missing:
        lines.append(f"Missing {len(missing)} patterns in brute-force BFS.")
        for s in missing[:20]:
            lines.append(f"missing {s}")

    if mismatches:
        lines.append(f"Counterexamples found: {len(mismatches)}")
        for s, got, want in mismatches[:20]:
            lines.append(f"seq={tuple(x + 1 for x in s)} dp={got} brute={want}")
    else:
        lines.append("No counterexamples found.")

    return "\n".join(lines)


def verify(max_len, random_trials=0):
    dist = brute_distances(max_len)
    return check_dist(dist, max_len, True, random_trials)


def run_tests():
    # Exhaustive verifier for all equality patterns of length <= 8.
    report8 = verify(8)
    print(report8)

    # If the small exhaustive verifier passes, stress/exhaustively check
    # canonical patterns up to length 10 and random raw sequences of length 9/10.
    if "No counterexamples found." in report8 and "Missing" not in report8:
        dist10 = brute_distances(10)
        report10 = check_dist(dist10, 10, True, 1000)
        print(report10)


def main():
    data = sys.stdin.buffer.read().split()
    if data:
        solve_original_from_ints(list(map(int, data)))
    else:
        run_tests()


if __name__ == "__main__":
    main()

