class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        # Apply all 'T' constraints first.
        p = [ord(c) - 97 for c in str2]
        fixed = [-1] * L

        for i, ch in enumerate(str1):
            if ch == 'T':
                for j, val in enumerate(p):
                    pos = i + j
                    old = fixed[pos]
                    if old == -1:
                        fixed[pos] = val
                    elif old != val:
                        return ""

        # If there are no 'F' constraints, the T constraints determine everything.
        if 'F' not in str1:
            for v in fixed:
                if v < 0:
                    return ""
            return ''.join(chr(97 + v) for v in fixed)

        # KMP prefix function for str2.
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j and p[i] != p[j]:
                j = pi[j - 1]
            if p[i] == p[j]:
                j += 1
            pi[i] = j

        # KMP automaton for states 0..m-1.
        # A full match is normalized immediately to pi[m-1].
        go = [[0] * 26 for _ in range(m)]
        first = p[0]
        row0 = go[0]
        for c in range(26):
            row0[c] = 1 if c == first else 0

        for state in range(1, m):
            pc = p[state]
            fallback = go[pi[state - 1]]
            row = go[state]
            for c in range(26):
                if c == pc:
                    row[c] = state + 1
                else:
                    row[c] = fallback[c]

        q_bits = [1 << q for q in range(m)]
        full_mask = (1 << m) - 1
        m1 = m - 1
        last_c = p[-1]
        last_bit = q_bits[m1]

        # nxt[c][q] = normalized next KMP state.
        # next_bit[c][q] = 1 << nxt[c][q].
        # preimage_char[c][t] = states q with nxt[c][q] == t.
        nxt = [[0] * m for _ in range(26)]
        next_bit = [[0] * m for _ in range(26)]
        preimage_char = [[0] * m for _ in range(26)]

        for c in range(26):
            nc = nxt[c]
            nb = next_bit[c]
            pre = preimage_char[c]
            for q in range(m):
                raw = go[q][c]
                q2 = pi[m1] if raw == m else raw
                nc[q] = q2
                bit = q_bits[q2]
                nb[q] = bit
                pre[q2] |= q_bits[q]

        del go

        # For free positions:
        # all_next[q] = next states reachable by some character.
        # nonmatch_next[q] = next states reachable by a character that does
        #                    NOT complete str2 (needed at F-window ends).
        # preimage_all/nonmatch are inverse masks for sparse feasible sets.
        all_next = [0] * m
        nonmatch_next = [0] * m
        preimage_all = [0] * m
        preimage_nonmatch = [0] * m

        for q in range(m):
            qb = q_bits[q]
            a = 0
            nm = 0
            for c in range(26):
                t = nxt[c][q]
                bit = q_bits[t]
                a |= bit
                preimage_all[t] |= qb
                # A full match can only happen from state m-1 with last_c.
                if not (q == m1 and c == last_c):
                    nm |= bit
                    preimage_nonmatch[t] |= qb
            all_next[q] = a
            nonmatch_next[q] = nm

        # f_end[pos] is True iff an F-window ends at pos.
        f_end = [False] * L
        for i, ch in enumerate(str1):
            if ch == 'F':
                f_end[i + m - 1] = True

        # Suffix feasibility DP.
        # feas[pos] is an m-bit mask: bit q is set iff suffix pos..L-1 can be
        # completed when the current normalized KMP state before pos is q.
        feas = [0] * (L + 1)
        feas[L] = full_mask
        SPARSE = 128

        for pos in range(L - 1, -1, -1):
            B = feas[pos + 1]
            if B == 0:
                return ""

            cfix = fixed[pos]
            fe = f_end[pos]

            # Very common dense case.
            if B == full_mask:
                if cfix == -1:
                    feas[pos] = full_mask
                elif fe and cfix == last_c:
                    cur = full_mask & ~last_bit
                    if cur == 0:
                        return ""
                    feas[pos] = cur
                else:
                    feas[pos] = full_mask
                continue

            cur = 0
            bc = B.bit_count()

            if cfix != -1:
                # Fixed character: deterministic transition.
                if bc <= SPARSE:
                    pre = preimage_char[cfix]
                    x = B
                    while x:
                        lsb = x & -x
                        t = lsb.bit_length() - 1
                        cur |= pre[t]
                        x ^= lsb
                        if cur == full_mask:
                            break
                    if fe and cfix == last_c:
                        cur &= ~last_bit
                else:
                    bits = next_bit[cfix]
                    if fe and cfix == last_c:
                        # State m-1 would complete str2.
                        for q in range(m1):
                            if bits[q] & B:
                                cur |= q_bits[q]
                    else:
                        for q in range(m):
                            if bits[q] & B:
                                cur |= q_bits[q]
            else:
                # Free character: exists a valid character leading into B.
                if bc <= SPARSE:
                    pre = preimage_nonmatch if fe else preimage_all
                    x = B
                    while x:
                        lsb = x & -x
                        t = lsb.bit_length() - 1
                        cur |= pre[t]
                        x ^= lsb
                        if cur == full_mask:
                            break
                else:
                    masks = nonmatch_next if fe else all_next
                    for q in range(m):
                        if masks[q] & B:
                            cur |= q_bits[q]

            if cur == 0:
                return ""
            feas[pos] = cur

        if (feas[0] & 1) == 0:
            return ""

        # Greedy lexicographic reconstruction using the feasibility table.
        chars = [chr(97 + i) for i in range(26)]
        res = []
        q = 0

        for pos in range(L):
            if (feas[pos] & q_bits[q]) == 0:
                return ""

            B = feas[pos + 1]
            fe = f_end[pos]
            cfix = fixed[pos]

            if cfix != -1:
                if fe and q == m1 and cfix == last_c:
                    return ""
                q2 = nxt[cfix][q]
                if (B & q_bits[q2]) == 0:
                    return ""
                res.append(chars[cfix])
                q = q2
            else:
                chosen = -1
                for cidx in range(26):
                    if fe and q == m1 and cidx == last_c:
                        continue
                    q2 = nxt[cidx][q]
                    if B & q_bits[q2]:
                        chosen = cidx
                        q = q2
                        break
                if chosen == -1:
                    return ""
                res.append(chars[chosen])

        return ''.join(res)

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        # All counts only need to be known up to k.  Using k + 1 lets us
        # distinguish "at least k" from "less than k" safely.
        cap = k + 1

        # Capped factorials.
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(cap, fact[i - 1] * i)

        def mul_cap(a: int, b: int) -> int:
            """Return min(cap, a * b) without relying on huge integers."""
            if a == 0 or b == 0:
                return 0
            if a > cap // b:
                return cap
            return min(cap, a * b)

        def count(o: int, e: int, start_parity: int) -> int:
            """
            Number of valid completions with o odd and e even numbers left,
            where the next position must have parity start_parity:
            1 = odd, 0 = even.
            """
            m = o + e

            if start_parity == 1:
                need_o = (m + 1) // 2
                need_e = m // 2
            else:
                need_o = m // 2
                need_e = (m + 1) // 2

            if o != need_o or e != need_e:
                return 0

            return mul_cap(fact[o], fact[e])

        odd_count = (n + 1) // 2
        even_count = n // 2

        # Total number of alternating permutations.
        if n % 2 == 0:
            total = mul_cap(mul_cap(fact[odd_count], fact[even_count]), 2)
        else:
            total = mul_cap(fact[odd_count], fact[even_count])

        if total < k:
            return []

        used = [False] * (n + 1)
        ans = []

        rem_o = odd_count
        rem_e = even_count
        last_parity = -1  # -1 means no previous element yet.

        for _ in range(n):
            chosen = False

            for x in range(1, n + 1):
                if used[x]:
                    continue

                parity = x & 1

                # Adjacent parities must differ.
                if last_parity != -1 and parity == last_parity:
                    continue

                if parity == 1:
                    if rem_o == 0:
                        continue
                    no, ne = rem_o - 1, rem_e
                else:
                    if rem_e == 0:
                        continue
                    no, ne = rem_o, rem_e - 1

                block = count(no, ne, 1 - parity)

                if block == 0:
                    continue

                if k > block:
                    k -= block
                else:
                    used[x] = True
                    ans.append(x)
                    rem_o, rem_e = no, ne
                    last_parity = parity
                    chosen = True
                    break

            if not chosen:
                return []

        return ans

import sys

MOD = 998244353

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    s = data[1]

    # Bit encoding of a relation on {0,1}:
    # bit 0: 0->0, bit 1: 0->1, bit 2: 1->0, bit 3: 1->1
    #
    # For s_i = 0, possible degree labels 0,1,2 give relations:
    labels0 = (2, 9, 4)
    # For s_i = 1, possible degree labels 0,1,2,3 give relations:
    labels1 = (2, 11, 13, 4)

    # comp[m][t] = composition m ; t
    comp = [[0] * 16 for _ in range(16)]
    for m in range(16):
        for t in range(16):
            res = 0
            for p in range(2):
                for q in range(2):
                    if (m >> (p * 2 + q)) & 1:
                        if (t >> (q * 2)) & 1:
                            res |= 1 << (p * 2)
                        if (t >> (q * 2 + 1)) & 1:
                            res |= 1 << (p * 2 + 1)
            comp[m][t] = res

    # Build sparse transition edges:
    # (from_mask, to_mask, multiplicity), where multiplicity is the number
    # of distinct degree labels producing this transition.
    edges = [[], []]
    for c, labels in enumerate((labels0, labels1)):
        for m in range(16):
            cnt = {}
            for t in labels:
                nm = comp[m][t]
                if nm:
                    cnt[nm] = cnt.get(nm, 0) + 1
            for nm, mult in cnt.items():
                edges[c].append((m, nm, mult))

    # Table by byte value of the input character.
    edge_table = [()] * 256
    edge_table[48] = tuple(edges[0])  # '0'
    edge_table[49] = tuple(edges[1])  # '1'

    # Initial relation is identity: mask 9 = bits 0 and 3.
    dp = [0] * 16
    dp[9] = 1
    ndp = [0] * 16
    zero = [0] * 16

    # Reduce modulo periodically to keep integers small while avoiding
    # 16 modulo operations per character.
    cnt = 0
    et = edge_table
    for ch in s:
        ndp[:] = zero
        for m, nm, mult in et[ch]:
            ndp[nm] += dp[m] * mult
        dp, ndp = ndp, dp

        cnt += 1
        if cnt == 16:
            dp = [x % MOD for x in dp]
            cnt = 0

    ans = 0
    for m in range(16):
        if m & 9:  # contains (0,0) or (1,1)
            ans += dp[m]
    print(ans % MOD)

if __name__ == "__main__":
    solve()

from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        C = 4 * side

        # Map each boundary point to a unique perimeter coordinate in [0, C).
        coords = []
        for x, y in points:
            if y == 0:
                t = x
            elif x == side:
                t = side + y
            elif y == side:
                t = 3 * side - x
            else:
                # x == 0, left side; (0, 0) was already handled above.
                t = C - y
            coords.append(t)

        coords.sort()
        n = len(coords)
        p2 = coords + [c + C for c in coords]
        m = 2 * n

        def can(d: int) -> bool:
            if d == 0:
                return True

            # k circular gaps of at least d cannot fit in circumference C.
            if d * k > C:
                return False

            # nxt[i] = first index j > i with p2[j] >= p2[i] + d.
            nxt = [m] * (m + 1)
            arr = p2
            j = 0
            for i in range(m):
                if j <= i:
                    j = i + 1
                target = arr[i] + d
                while j < m and arr[j] < target:
                    j += 1
                nxt[i] = j

            limit = C - d
            steps = k - 1
            step_range = range(steps)

            # Try every point as the first chosen point in circular order.
            for start in range(n):
                idx = start
                max_idx = start + n  # indices [start, start+n) contain each point once
                for _ in step_range:
                    idx = nxt[idx]
                    if idx >= max_idx:
                        break
                else:
                    # Wrap-around gap from last chosen point back to start.
                    if arr[idx] <= arr[start] + limit:
                        return True

            return False

        # For k >= 4, the answer is never larger than side.
        # Also, k gaps of length d require d <= C // k.
        lo, hi = 0, min(side, C // k)

        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

