    main()

from typing import List
from bisect import bisect_left


class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        if not intervals:
            return []

        n = len(intervals)

        # Sort by right endpoint, keeping the original index.
        arr = sorted((r, l, idx, w) for idx, (l, r, w) in enumerate(intervals))
        ends = [item[0] for item in arr]

        # p[i] = number of intervals ending strictly before interval i starts.
        bl = bisect_left
        p = [bl(ends, item[1]) for item in arr]
        del ends

        # Insert x into a sorted tuple of length at most 3.
        def add_idx(t, x):
            ln = len(t)
            if ln == 0:
                return (x,)
            if ln == 1:
                a = t[0]
                if x < a:
                    return (x, a)
                return (a, x)
            if ln == 2:
                a, b = t
                if x < a:
                    return (x, a, b)
                if x < b:
                    return (a, x, b)
                return (a, b, x)

            a, b, d = t
            if x < a:
                return (x, a, b, d)
            if x < b:
                return (a, x, b, d)
            if x < d:
                return (a, b, x, d)
            return (a, b, d, x)

        # DP for exact counts. prev_* is for count c-1, curr_* for count c.
        prev_w = [0] * (n + 1)
        prev_t = [()] * (n + 1)

        best_w = 0
        best_t = ()

        for _ in range(1, 5):
            curr_w = [-1] * (n + 1)
            curr_t = [None] * (n + 1)

            cw = curr_w
            ct = curr_t
            pw = prev_w
            pt = prev_t
            pp = p
            aa = arr
            add = add_idx

            for i in range(1, n + 1):
                # Skip interval i-1.
                bw = cw[i - 1]
                bt = ct[i - 1]

                # Take interval i-1.
                pi = pp[i - 1]
                base_w = pw[pi]
                if base_w != -1:
                    item = aa[i - 1]
                    tw = base_w + item[3]

                    if tw > bw:
                        bw = tw
                        bt = add(pt[pi], item[2])
                    elif tw == bw:
                        tt = add(pt[pi], item[2])
                        if bt is None or tt < bt:
                            bt = tt

                cw[i] = bw
                ct[i] = bt

            if cw[n] != -1:
                if cw[n] > best_w or (
                    cw[n] == best_w and (best_t is None or ct[n] < best_t)
                ):
                    best_w = cw[n]
                    best_t = ct[n]

            prev_w, prev_t = curr_w, curr_t

        return list(best_t)


if __name__ == "__main__":
    sol = Solution()

    assert sol.maximumWeight(
        [[1, 3, 2], [4, 5, 2], [1, 5, 5], [6, 9, 3], [6, 7, 1], [8, 9, 1]]
    ) == [2, 3]

    assert sol.maximumWeight(
        [[5, 8, 1], [6, 7, 7], [4, 7, 3], [9, 10, 6], [7, 8, 2], [11, 14, 3], [3, 5, 5]]
    ) == [1, 3, 5, 6]

    # Touching boundaries overlap; separated points do not.
    assert sol.maximumWeight([[1, 2, 10], [2, 3, 10]]) == [0]
    assert sol.maximumWeight([[1, 1, 5], [2, 2, 5]]) == [0, 1]

    # All overlapping, equal and unequal weights.
    assert sol.maximumWeight([[1, 5, 5], [2, 4, 5], [3, 6, 5]]) == [0]
    assert sol.maximumWeight([[1, 5, 1], [2, 4, 2], [3, 6, 3]]) == [2]

    # Ties across different chosen counts.
    assert sol.maximumWeight([[1, 10, 10], [1, 1, 5], [2, 2, 5]]) == [0]
    assert sol.maximumWeight([[1, 1, 5], [2, 2, 5], [3, 10, 10]]) == [0, 1]

    # Large coordinates and boundary at 1e9.
    assert sol.maximumWeight(
        [[1, 1000000000, 1000000000], [1000000000, 1000000000, 1000000000]]
    ) == [0]
    assert sol.maximumWeight(
        [[1, 999999999, 1], [1000000000, 1000000000, 1]]
    ) == [0, 1]

    # More than four compatible intervals: choose the lexicographically smallest four.
    assert sol.maximumWeight([[i, i, 1] for i in range(1, 10)]) == [0, 1, 2, 3]

    # A single heavy interval beats several lighter compatible intervals.
    assert sol.maximumWeight(
        [[1, 1, 1], [2, 2, 1], [3, 3, 1], [4, 4, 1], [5, 5, 100]]
    ) == [4]

    # Duplicate overlapping intervals choose the smallest index.
    assert sol.maximumWeight([[1, 2, 5], [1, 2, 5], [3, 4, 5]]) == [0, 2]

    # Empty input is handled even though constraints have n >= 1.
    assert sol.maximumWeight([]) == []

from typing import List
import random
from itertools import product


def _merge(a, b):
    """Merge two segment summaries. None represents the empty sequence."""
    if a is None:
        return b
    if b is None:
        return a

    sa, pa, ua, ba = a
    sb, pb, ub, bb = b

    s = sa + sb

    t = sa + pb
    p = pa if pa >= t else t

    t = sb + ua
    u = ub if ub >= t else t

    best = ba if ba >= bb else bb
    t = ua + pb
    if t > best:
        best = t

    return (s, p, u, best)


class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        if not nums:
            return 0

        n = len(nums)

        # Original maximum subarray sum, and group negative values by positions.
        ans = cur = nums[0]
        pos = {}

        for i in range(n):
            v = nums[i]

            if i:
                if cur < 0:
                    cur = v
                else:
                    cur += v
                if cur > ans:
                    ans = cur

            if v < 0:
                lst = pos.get(v)
                if lst is None:
                    pos[v] = [i]
                else:
                    lst.append(i)

        # If there is no negative value, deleting non-negative values cannot help.
        # If n == 1, deleting the only value is invalid.
        if not pos or n == 1:
            return ans

        # If all elements are the same negative value, deletion is invalid.
        if len(pos) == 1:
            only = next(iter(pos.values()))
            if len(only) == n:
                return ans

        mg = _merge

        # Prefix summaries: pref[i] summarizes nums[0:i].
        pref = [None] * (n + 1)
        for i in range(n):
            v = nums[i]
            pref[i + 1] = mg(pref[i], (v, v, v, v))

        # Suffix summaries: suff[i] summarizes nums[i:n].
        suff = [None] * (n + 1)
        for i in range(n - 1, -1, -1):
            v = nums[i]
            suff[i] = mg((v, v, v, v), suff[i + 1])

        # A segment tree is needed only for internal blocks between occurrences.
        need_tree = False
        for lst in pos.values():
            m = len(lst)
            if m > 1:
                prev = lst[0] + 1
                for j in range(1, m):
                    p = lst[j]
                    if prev < p:
                        need_tree = True
                        break
                    prev = p + 1
                if need_tree:
                    break

        query = None
        if need_tree:
            size = 1
            while size < n:
                size <<= 1

            tree = [None] * (size << 1)
            base = size

            for i in range(n):
                v = nums[i]
                tree[base + i] = (v, v, v, v)

            for i in range(base - 1, 0, -1):
                tree[i] = mg(tree[i << 1], tree[(i << 1) | 1])

            def query(l, r, tree=tree, base=base, mg=mg):
                if l >= r:
                    return None

                l += base
                r += base
                left = None
                right = None

                while l < r:
                    if l & 1:
                        left = mg(left, tree[l])
                        l += 1
                    if r & 1:
                        r -= 1
                        right = mg(tree[r], right)
                    l >>= 1
                    r >>= 1

                return mg(left, right)

        # For each negative value, concatenate all blocks that remain after deletion.
        for lst in pos.values():
            m = len(lst)

            # Removing this value would empty the array.
            if m == n:
                continue

            # Single occurrence: only prefix and suffix blocks.
            if m == 1:
                p = lst[0]
                acc = pref[p] if p > 0 else None
                if p + 1 < n:
                    acc = mg(acc, suff[p + 1])

                if acc is not None and acc[3] > ans:
                    ans = acc[3]
                continue

            acc = None

            first = lst[0]
            if first > 0:
                acc = pref[first]

            prev = first + 1
            for j in range(1, m):
                p = lst[j]
                if prev < p:
                    acc = mg(acc, query(prev, p))
                prev = p + 1

            if prev < n:
                acc = mg(acc, suff[prev])

            if acc is not None and acc[3] > ans:
                ans = acc[3]

        return ans


def _max_subarray_brute(arr):
    """Independent O(n^2) maximum subarray sum for the checker."""
    best = arr[0]
    n = len(arr)
    for i in range(n):
        s = 0
        for j in range(i, n):
            s += arr[j]
            if s > best:
                best = s
    return best


def _brute(nums):
    ans = _max_subarray_brute(nums)
    seen = set()

    for x in nums:
        if x in seen:
            continue
        seen.add(x)

        arr = [v for v in nums if v != x]
        if not arr:
            continue

        val = _max_subarray_brute(arr)
        if val > ans:
            ans = val

    return ans


if __name__ == "__main__":
    sol = Solution()

    sample_cases = [
        ([-3, 2, -2, -1, 3, -2, 3], 7),
        ([1, 2, 3, 4], 10),
    ]

    sample_ok = True
    for nums, expected in sample_cases:
        got = sol.maxSubarraySum(nums)
        if got != expected:
            sample_ok = False
            print("Sample fail:", nums, got, expected)

    print("Sample verdict:", "pass" if sample_ok else "fail")

    random.seed(123456)
    random_ok = True
    random_fail = None

    for _ in range(1000):
        n = random.randint(1, 8)
        nums = [random.randint(-5, 5) for _ in range(n)]

        got = sol.maxSubarraySum(nums)
        expected = _brute(nums)

        if got != expected:
            random_ok = False
            random_fail = (nums, got, expected)
            break

    if random_fail is not None:
        print("Random fail:", random_fail)

    print("Random verdict:", "pass" if random_ok else "fail")

    exhaustive_ok = None
    exhaustive_fail = None

    if random_ok:
        exhaustive_ok = True

        for n in range(1, 5):
            for tup in product(range(-2, 3), repeat=n):
                nums = list(tup)

                got = sol.maxSubarraySum(nums)
                expected = _brute(nums)

                if got != expected:
                    exhaustive_ok = False
                    exhaustive_fail = (nums, got, expected)
                    break

            if not exhaustive_ok:
                break

        if exhaustive_fail is not None:
            print("Exhaustive fail:", exhaustive_fail)

    if exhaustive_ok is not None:
        print("Exhaustive verdict:", "pass" if exhaustive_ok else "fail")

import sys


def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    N = int(data[0])
    K = int(data[1])

    A = [0] * N
    total_xor = 0
    for i in range(N):
        v = int(data[2 + i])
        A[i] = v
        total_xor ^= v

    # Complement symmetry:
    # XOR(chosen K) = total_xor XOR XOR(excluded N-K).
    # Enumerate the smaller side.
    if K <= N - K:
        M = K
        mask = 0
    else:
        M = N - K
        mask = total_xor

    if M == 0:
        sys.stdout.write(str(mask))
        return

    n = N
    arr = A

    # Fast paths for the cases where N can be very large.
    if M == 1:
        if mask == 0:
            ans = max(arr)
        else:
            ans = 0
            m = mask
            for v in arr:
                y = m ^ v
                if y > ans:
                    ans = y
        sys.stdout.write(str(ans))
        return

    if M == 2:
        ans = 0
        a = arr
        if mask == 0:
            for i in range(n - 1):
                ai = a[i]
                for j in range(i + 1, n):
                    y = ai ^ a[j]
                    if y > ans:
                        ans = y
        else:
            m = mask
            for i in range(n - 1):
                ai = a[i]
                for j in range(i + 1, n):
                    y = m ^ ai ^ a[j]
                    if y > ans:
                        ans = y
        sys.stdout.write(str(ans))
        return

    sys.setrecursionlimit(1000000)
    ans = 0

    # Enumerate combinations by index, carrying the current XOR.
    # Base cases rem == 1, 2, 3 avoid many leaf function calls.
    def dfs(start, rem, x, arr=arr, n=n, mask=mask):
        nonlocal ans

        if rem == 1:
            cur = ans
            m = mask
            a = arr
            for i in range(start, n):
                y = m ^ x ^ a[i]
                if y > cur:
                    cur = y
            ans = cur
            return

        if rem == 2:
            cur = ans
            m = mask
            a = arr
            for i in range(start, n - 1):
                xi = x ^ a[i]
                for j in range(i + 1, n):
                    y = m ^ xi ^ a[j]
                    if y > cur:
                        cur = y
            ans = cur
            return

        if rem == 3:
            cur = ans
            m = mask
            a = arr
            for i in range(start, n - 2):
                xi = x ^ a[i]
                for j in range(i + 1, n - 1):
                    xij = xi ^ a[j]
                    for k in range(j + 1, n):
                        y = m ^ xij ^ a[k]
                        if y > cur:
                            cur = y
            ans = cur
            return

        end = n - rem + 1
        a = arr
        for i in range(start, end):
            dfs(i + 1, rem - 1, x ^ a[i])

    dfs(0, M, 0)
    sys.stdout.write(str(ans))


if __name__ == "__main__":
    solve()

