class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        if n <= 1:
            return 1

        # Doing no operations is always allowed, so the original maximum run
        # length is a valid upper bound for the answer.
        hi = 1
        run = 1
        for i in range(1, n):
            if s[i] == s[i - 1]:
                run += 1
            else:
                run = 1
            if run > hi:
                hi = run

        def feasible(limit: int) -> bool:
            # Any cost above numOps is useless; cap it to keep states small.
            INF = numOps + 1

            # dp0[length] / dp1[length]:
            # minimum flips for the processed prefix ending with 0 / 1
            # and having current identical-character run length == length.
            # Index 0 is unused.
            dp0 = [INF] * (limit + 1)
            dp1 = [INF] * (limit + 1)

            if s[0] == '0':
                dp0[1] = 0
                dp1[1] = 1
            else:
                dp0[1] = 1
                dp1[1] = 0

            best0 = min(dp0)
            best1 = min(dp1)

            for ch in s[1:]:
                target = 1 if ch == '1' else 0
                ndp0 = [INF] * (limit + 1)
                ndp1 = [INF] * (limit + 1)

                # Extend an existing run if it would not exceed limit.
                if limit > 1:
                    if target == 0:
                        for length in range(1, limit):
                            # Keep current bit 0: no extra flip.
                            v = dp0[length]
                            if v < ndp0[length + 1]:
                                ndp0[length + 1] = v

                            # Keep current bit 1: flip to 0.
                            v = dp1[length]
                            if v + 1 < ndp1[length + 1]:
                                ndp1[length + 1] = v + 1
                    else:
                        for length in range(1, limit):
                            # Keep current bit 0: flip to 1.
                            v = dp0[length]
                            if v + 1 < ndp0[length + 1]:
                                ndp0[length + 1] = v + 1

                            # Keep current bit 1: no extra flip.
                            v = dp1[length]
                            if v < ndp1[length + 1]:
                                ndp1[length + 1] = v

                # Switch to the opposite bit, resetting run length to 1.
                old_best0, old_best1 = best0, best1
                if target == 1:
                    # Previous bit 0 -> current bit 1, no flip.
                    if old_best0 < ndp1[1]:
                        ndp1[1] = old_best0

                    # Previous bit 1 -> current bit 0, one flip.
                    if old_best1 + 1 < ndp0[1]:
                        ndp0[1] = old_best1 + 1
                else:
                    # Previous bit 1 -> current bit 0, no flip.
                    if old_best1 < ndp0[1]:
                        ndp0[1] = old_best1

                    # Previous bit 0 -> current bit 1, one flip.
                    if old_best0 + 1 < ndp1[1]:
                        ndp1[1] = old_best0 + 1

                dp0, dp1 = ndp0, ndp1
                best0 = min(dp0)
                best1 = min(dp1)

                # Future characters can only add non-negative flip costs.
                if best0 > numOps and best1 > numOps:
                    return False

            return best0 <= numOps or best1 <= numOps

        lo = 1
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo

import sys
from bisect import bisect_left, bisect_right


def solve():
    input = sys.stdin.buffer.readline

    first = input().split()
    if not first:
        return

    N = int(first[0])
    M = int(first[1])
    curx = int(first[2])
    cury = int(first[3])

    h_lines = {}
    v_lines = {}

    for i in range(N):
        x, y = map(int, input().split())

        lst = h_lines.get(y)
        if lst is None:
            h_lines[y] = [(x, i)]
        else:
            lst.append((x, i))

        lst = v_lines.get(x)
        if lst is None:
            v_lines[x] = [(y, i)]
        else:
            lst.append((y, i))

    for y, lst in h_lines.items():
        lst.sort()
        xs = [p[0] for p in lst]
        ids = [p[1] for p in lst]
        h_lines[y] = (xs, ids)

    for x, lst in v_lines.items():
        lst.sort()
        ys = [p[0] for p in lst]
        ids = [p[1] for p in lst]
        v_lines[x] = (ys, ids)

    h_updates = {}
    v_updates = {}

    bl = bisect_left
    br = bisect_right
    h_get = h_lines.get
    v_get = v_lines.get

    for _ in range(M):
        d, c = input().split()
        c = int(c)

        if d == b'U':
            ny = cury + c
            line = v_get(curx)
            if line is not None:
                ys = line[0]
                l = bl(ys, cury)
                r = br(ys, ny) - 1
                if l <= r:
                    lst = v_updates.get(curx)
                    if lst is None:
                        v_updates[curx] = [(l, r)]
                    else:
                        lst.append((l, r))
            cury = ny

        elif d == b'D':
            ny = cury - c
            line = v_get(curx)
            if line is not None:
                ys = line[0]
                l = bl(ys, ny)
                r = br(ys, cury) - 1
                if l <= r:
                    lst = v_updates.get(curx)
                    if lst is None:
                        v_updates[curx] = [(l, r)]
                    else:
                        lst.append((l, r))
            cury = ny

        elif d == b'L':
            nx = curx - c
            line = h_get(cury)
            if line is not None:
                xs = line[0]
                l = bl(xs, nx)
                r = br(xs, curx) - 1
                if l <= r:
                    lst = h_updates.get(cury)
                    if lst is None:
                        h_updates[cury] = [(l, r)]
                    else:
                        lst.append((l, r))
            curx = nx

        else:  # b'R'
            nx = curx + c
            line = h_get(cury)
            if line is not None:
                xs = line[0]
                l = bl(xs, curx)
                r = br(xs, nx) - 1
                if l <= r:
                    lst = h_updates.get(cury)
                    if lst is None:
                        h_updates[cury] = [(l, r)]
                    else:
                        lst.append((l, r))
            curx = nx

    covered = bytearray(N)

    for key, updates in h_updates.items():
        xs, ids = h_lines[key]
        diff = [0] * (len(xs) + 1)

        for l, r in updates:
            diff[l] += 1
            diff[r + 1] -= 1

        cur = 0
        for i in range(len(xs)):
            cur += diff[i]
            if cur > 0:
                covered[ids[i]] = 1

    for key, updates in v_updates.items():
        ys, ids = v_lines[key]
        diff = [0] * (len(ys) + 1)

        for l, r in updates:
            diff[l] += 1
            diff[r + 1] -= 1

        cur = 0
        for i in range(len(ys)):
            cur += diff[i]
            if cur > 0:
                covered[ids[i]] = 1

    sys.stdout.write(f"{curx} {cury} {sum(covered)}\n")


if __name__ == "__main__":
    solve()

import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    adj = [[] for _ in range(n)]
    deg = [0] * n

    idx = 1
    for _ in range(n - 1):
        u = data[idx] - 1
        v = data[idx + 1] - 1
        idx += 2

        adj[u].append(v)
        adj[v].append(u)
        deg[u] += 1
        deg[v] += 1

    del data

    getdeg = deg.__getitem__
    best = 3  # minimum valid snowflake has 3 vertices

    for a in adj:
        if best >= n:
            best = n
            break

        l = len(a)
        if l == 0:
            continue

        if l == 1:
            d = deg[a[0]]
            if d >= 2:
                val = d + 1
                if val > best:
                    best = val
            continue

        if l == 2:
            v0 = a[0]
            v1 = a[1]
            d0 = deg[v0]
            d1 = deg[v1]

            if d0 < d1:
                d0, d1 = d1, d0

            if d0 >= 2:
                val = d0 + 1
                if val > best:
                    best = val

                if d1 >= 2:
                    val = 1 + 2 * d1
                    if val > best:
                        best = val
            continue

        a.sort(key=getdeg, reverse=True)

        x = 0
        for v in a:
            d = deg[v]
            if d <= 1:
                break

            x += 1
            val = 1 + x * d
            if val > best:
                best = val

    if best > n:
        best = n

    print(n - best)


